# Merch Forge · explicit online provider access check (NETWORK yes, IMAGE GENERATION no)
Set-StrictMode -Version 2.0
$ErrorActionPreference='Stop'
[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12
function V($o,[string]$n){if($null-eq$o){return $null};$p=$o.PSObject.Properties[$n];if($null-eq$p){return $null};return $p.Value}
function Secret([string]$Path){$e=([string]$env:OPENAI_API_KEY).Trim();if($e){return $e};if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){return ''};$enc=(Get-Content -LiteralPath $Path -Raw -Encoding UTF8).Trim();if(-not $enc){return ''};$sec=$enc|ConvertTo-SecureString;$ptr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($sec);try{return [Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr)}}
function WriteAtomic([string]$Path,$Object){$tmp=$Path+'.tmp-'+[Guid]::NewGuid().ToString('N');$utf8=New-Object Text.UTF8Encoding -ArgumentList $false;[IO.File]::WriteAllText($tmp,($Object|ConvertTo-Json -Depth 20),$utf8);Move-Item -LiteralPath $tmp -Destination $Path -Force}
$state=Join-Path $env:LOCALAPPDATA 'MerchForge';$reportPath=Join-Path $state 'provider-online-check.json';if(-not(Test-Path $state)){New-Item -ItemType Directory -Path $state -Force|Out-Null};$ok=$false;$model='';$rid='';$detail='';$status=0
try{$cfgPath=Join-Path $state 'provider-config.json';if(-not(Test-Path -LiteralPath $cfgPath -PathType Leaf)){throw 'Provider config is missing.'};$cfg=Get-Content -LiteralPath $cfgPath -Raw -Encoding UTF8|ConvertFrom-Json;if(-not [bool](V $cfg 'enabled')){throw 'Provider is disabled.'};$model=[string](V $cfg 'model');if($model -notin @('gpt-image-2.5-sunburst-2026-09-08','gpt-image-2.5-flare-2026-09-08','gpt-image-2.5-sunburst','gpt-image-2.5-flare')){throw 'Configured model is outside the online-check allowlist.'};$key=Secret (Join-Path $state 'provider-secrets\openai-image.sec');if([string]::IsNullOrWhiteSpace($key)){throw 'Provider credential is unavailable.'};$uri='https://api.openai.com/v1/models/'+$model;$resp=Invoke-WebRequest -UseBasicParsing -Method Get -Uri $uri -Headers @{Authorization=('Bearer '+$key)} -TimeoutSec 30 -MaximumRedirection 0;$status=[int]$resp.StatusCode;try{$rid=[string]$resp.Headers['x-request-id']}catch{};$j=$resp.Content|ConvertFrom-Json;if($status-ne200 -or [string](V $j 'id') -ne $model -or [string](V $j 'object') -ne 'model'){throw 'Provider model-access response did not match the configured model.'};$ok=$true;$detail='Credential and model access verified. No image-generation endpoint was called.'}catch{$detail=$_.Exception.Message}
$report=[ordered]@{schema='forge.provider_online_check.v1';pass=$ok;provider_key='openai_image_api';model=$model;network_called=$true;http_method='GET';endpoint_kind='model_metadata';image_generation_called=$false;paid_image_request_called=$false;http_status=$status;provider_request_id=$rid;detail=$detail;checked_at=[DateTime]::UtcNow.ToString('o')};WriteAtomic $reportPath $report;Write-Output ($report|ConvertTo-Json -Depth 20);if($ok){exit 0}else{exit 12}
